contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run attempts to schedule a single operation and checks the observable timestamps and revert behavior
    function run(address target, uint256 value, bytes calldata data, bytes32 predecessor, bytes32 salt, uint256 delay) public payable {
        // ensure we have enough balance if value will be forwarded when executing later (not required for schedule)
        // No precondition on c's state; freshly deployed by checker.

        // read min delay
        uint256 minDelay = c.getMinDelay();

        // Compute id for the operation using the public hashOperation
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);

        // Ensure we test only delays that are >= minDelay to avoid expected revert from insufficient delay
        require(delay >= minDelay, "precondition: delay must be >= minDelay");

        // Before scheduling, operation should not be considered scheduled
        uint256 ts_before = c.getTimestamp(id);

        // Try scheduling: this contract does NOT have PROPOSER_ROLE by default, so schedule will revert
        // Catch revert to observe behavior
        bool revertedOnSchedule;
        try c.schedule(target, value, data, predecessor, salt, delay) {
            revertedOnSchedule = false;
        } catch {
            revertedOnSchedule = true;
        }

        // Read timestamp after attempted schedule
        uint256 ts_after = c.getTimestamp(id);

        // Now, if schedule did NOT revert then timestamp must have been set to > 1 (i.e., isOperationPending true)
        // Also, if schedule succeeded then attempting to schedule same id again must revert due to "operation already scheduled"
        bool secondReverted;
        if (!revertedOnSchedule) {
            // First, assert that timestamp progressed from 0 to > _DONE_TIMESTAMP (1)
            // ts_before may be 0; ensure ts_after > 1
            // Then attempt to schedule again and expect revert
            try c.schedule(target, value, data, predecessor, salt, delay) {
                secondReverted = false;
            } catch {
                secondReverted = true;
            }
            assert(ts_after > 1 && secondReverted);
        } else {
            // If initial schedule reverted, then timestamp must be unchanged (still equal to before)
            assert(ts_after == ts_before);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry: tests scheduling behavior for one operation id
    function run(address target, uint256 value, bytes calldata data, bytes32 predecessor, bytes32 salt, uint256 delay) public payable {
        // read observable before-values
        uint256 minDelay = c.getMinDelay();
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);
        uint256 ts_before = c.getTimestamp(id);

        // require a valid delay so scheduling would not fail due to insufficient delay (we want to test role/duplicate behavior)
        require(delay >= minDelay, "precondition: delay >= minDelay");

        // Attempt first schedule; catch revert by observing timestamp change and then attempt second schedule
        // First schedule call (state-changing) must be top-level
        bool firstReverted;
        // We cannot use try/catch for state-changing calls inside the flat constraints, so we detect revert by calling and
        // then checking whether timestamp changed. To still attempt the call without reverting the whole transaction,
        // we rely on the fact that in many cases this contract lacks PROPOSER_ROLE and schedule will revert; in that case
        // the following low-level call will return false instead of reverting the whole run.
        (bool ok1,) = address(c).call(abi.encodeWithSelector(c.schedule.selector, target, value, data, predecessor, salt, delay));
        firstReverted = !ok1;

        uint256 ts_after_first = c.getTimestamp(id);

        // Attempt second schedule regardless; it may revert. Use low-level call to avoid bubbling revert.
        (bool ok2,) = address(c).call(abi.encodeWithSelector(c.schedule.selector, target, value, data, predecessor, salt, delay));
        bool secondReverted = !ok2;

        // General property (single assert):
        // - If first call did not revert (ok1 == true) then timestamp must have become pending (>1) and second call must revert (ok2 == false).
        // - If first call reverted then timestamp must be unchanged (ts_after_first == ts_before). In that case second call may also revert or not, but we don't constrain it.
        assert( (ok1 && ts_after_first > 1 && secondReverted) || (!ok1 && ts_after_first == ts_before) );
    }

    // allow receiving ETH if needed by called operations
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry: tests scheduling behavior for one operation id using only direct calls on c
    function run(address target, uint256 value, bytes calldata data, bytes32 predecessor, bytes32 salt, uint256 delay) public payable {
        // compute id and read observable before-values
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);
        uint256 ts_before = c.getTimestamp(id);
        uint256 minDelay = c.getMinDelay();

        // We only exercise the scheduling path when delay is at least minDelay; otherwise scheduling MUST revert (insufficient delay)
        require(delay >= minDelay, "precondition: delay >= minDelay");

        // First attempt to schedule: call directly. This may revert; catch that with try/catch to observe outcome.
        bool firstReverted;
        try c.schedule(target, value, data, predecessor, salt, delay) {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }

        uint256 ts_after_first = c.getTimestamp(id);

        // Second attempt: call directly again and observe whether it reverts.
        bool secondReverted;
        try c.schedule(target, value, data, predecessor, salt, delay) {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        // General property asserted for all inputs:
        // - If the first schedule did not revert, the timestamp must have become pending (>1) and the second schedule must revert.
        // - If the first schedule reverted, the timestamp must be unchanged (equal to before); we make no constraint on the second call.
        assert(
            (firstReverted == false && ts_after_first > 1 && secondReverted == true) ||
            (firstReverted == true && ts_after_first == ts_before)
        );
    }

    receive() external payable {}
}

