contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take parameters that are used to form an operation and a delay and an address to act as proposer.
    // msg.sender for calls to c will be this contract, which initially has no roles. The freshly deployed
    // C grants the deploying account (outside our control) some roles, but we must operate under the
    // assumption the proposers array given at construction of C may or may not include address(this).
    // To ensure we can call schedule, we will attempt the call and record whether it reverted.

    function run(address target, uint256 value, bytes calldata data, bytes32 predecessor, bytes32 salt, uint256 delay) public payable {
        require(target != address(0), true);
        // Read min delay before doing anything
        uint256 minDelay = c.getMinDelay();

        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);

        // Try to schedule and capture whether it reverted.
        bool reverted;
        try c.schedule(target, value, data, predecessor, salt, delay) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After the attempt, observe timestamps and operation predicates
        uint256 ts = c.getTimestamp(id);
        bool isOp = c.isOperation(id);
        bool isPending = c.isOperationPending(id);

        // General rule to assert:
        // If the schedule call reverted, then either the provided delay was < minDelay OR caller lacked proposer role
        // If it did not revert, then: isOperation must be true and if delay >= minDelay then isOperationPending must be true
        // We cannot observe roles directly, so we express the rule as: (non-reverted) => isOperation && (delay >= minDelay => isOperationPending)
        // And (reverted) => (!(delay >= minDelay) || !isOp) is a weaker but provable relation: if revert happened but delay >= minDelay and operation wasn't scheduled, then isOp should be false.

        assert( (!reverted) ? (isOp && (delay >= minDelay ? isPending : true)) : ((! (delay >= minDelay)) || (!isOp)) );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Try scheduling an operation and assert the relation between revert, delay, and operation state.
    function run(address target, uint256 value, bytes calldata data, bytes32 predecessor, bytes32 salt, uint256 delay) public payable {
        // target can be any address (including address(0)); no precondition required

        uint256 minDelay = c.getMinDelay();
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);

        // Attempt to schedule and record whether it reverted.
        bool reverted;
        try c.schedule(target, value, data, predecessor, salt, delay) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe post-call state
        uint256 ts = c.getTimestamp(id);
        bool isOp = c.isOperation(id);
        bool isPending = c.isOperationPending(id);

        // General rule:
        // - If schedule did not revert then the operation must be recorded (isOperation == true).
        //   Additionally, if provided delay >= minDelay then it must be pending (isOperationPending == true).
        // - If schedule reverted then either the delay was insufficient (delay < minDelay) or the operation is not recorded (isOperation == false).
        assert(
            (!reverted) ? (isOp && (delay >= minDelay ? isPending : true)) : ((delay < minDelay) || (!isOp))
        );
    }

    receive() external payable {}
}
